1	#!/usr/bin/env node
2	import fs from 'node:fs/promises';
3	import path from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { validateSpec } from './gate/validate.js';
6	import { renderJson, renderText } from './gate/report.js';
7	import { verdictFrom } from './gate/schema.js';
8	import { draftGateSection, smartReview } from './pipeline/agent.js';
9	
10	const TEMPLATE_PATH = fileURLToPath(new URL('../assets/rai-spec-template.md', import.meta.url));
11	
12	const CI_WORKFLOW = `name: Responsible AI Gate
13	on:
14	  pull_request:
15	  push:
16	    branches: [main]
17	jobs:
18	  rai-gate:
19	    runs-on: ubuntu-latest
20	    steps:
21	      - uses: actions/checkout@v4
22	      - uses: actions/setup-node@v4
23	        with:
24	          node-version: '20'
25	      # Blocks the build until every Responsible AI Gate check in the spec is answered.
26	      - run: npx frai-gate check FRAI-SPEC.md
27	`;
28	
29	const HELP = `frai-gate - the FRAI Gate: a Responsible AI Gate for specs
30	
31	Usage:
32	  frai-gate init [--out <file>] [--ci]   Drop the RAI spec template into the repo (default: FRAI-SPEC.md);
33	                                         --ci also writes .github/workflows/rai-gate.yml so the gate
34	                                         runs on every PR
35	  frai-gate check <spec.md> [options]    Validate the spec's Responsible AI Gate
36	      --smart                            Add an AI quality review of the gate answers (Claude Agent SDK)
37	      --json                             Machine-readable output
38	  frai-gate draft [--out <file>] [--print]
39	                                         Scan this repo with a read-only agent and draft a filled-in
40	                                         gate section grounded in the code (default out: rai-gate-draft.md)
41	
42	Exit codes: 0 = PASS/WARN, 1 = BLOCK, 2 = usage/error.
43	The smart commands (draft, check --smart) use the Claude Agent SDK and need Claude Code
44	authentication or ANTHROPIC_API_KEY. Model override: FRAI_GATE_MODEL (default claude-opus-5).`;
45	
46	interface Args {
47	  command: string | undefined;
48	  positional: string[];
49	  flags: Map<string, string | true>;
50	}
51	
52	function parseArgs(argv: string[]): Args {
53	  const [command, ...rest] = argv;
54	  const positional: string[] = [];
55	  const flags = new Map<string, string | true>();
56	  for (let i = 0; i < rest.length; i += 1) {
57	    const arg = rest[i];
58	    if (arg.startsWith('--')) {
59	      const name = arg.slice(2);
60	      const next = rest[i + 1];
61	      if (next !== undefined && !next.startsWith('--') && ['out', 'spec'].includes(name)) {
62	        flags.set(name, next);
63	        i += 1;
64	      } else {
65	        flags.set(name, true);
66	      }
67	    } else {
68	      positional.push(arg);
