import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** A template field line whose value was never filled in, e.g. `- **Retention**:` or `- **Retention:**` */
const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^:*]*:?\*\*\s*:?\s*$/;

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const fieldLine = body
    .split(/\r?\n/)
    .find((l) => /\*\*tier\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
  const haystacks = fieldLine ? [fieldLine] : [body];
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function answeredText(body: string): string {
  const lines = body.split(/\r?\n/);
  const result: string[] = [];
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (EMPTY_FIELD.test(line)) {
      // Check if there's indented content below this empty field
      let hasIndentedContent = false;
      if (i + 1 < lines.length) {
        const nextLine = lines[i + 1];
        // Check if next line is indented (starts with whitespace beyond the list marker level)
        // or is blank (which might separate the field from its nested content)
        if (/^\s{2,}/.test(nextLine) || nextLine.trim() === '') {
          hasIndentedContent = true;
        }
      }
      if (!hasIndentedContent) {
        // Only skip if there's truly no content below
        continue;
      }
    }
    result.push(line);
  }
  return result.join('\n').trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
