// Simple test to verify the validation changes
const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^:*]*:?\*\*\s*(\([^)]*\))?\s*:?\s*$/;

// Test cases
const testCases = [
  // Should match (empty fields)
  { text: '- **Tier**:', shouldMatch: true, desc: 'colon after bold' },
  { text: '- **Tier:**', shouldMatch: true, desc: 'colon inside bold' },
  { text: '- **Tier** (a / b / c):', shouldMatch: true, desc: 'with enum hint' },
  { text: '- **Retention** (30 days):', shouldMatch: true, desc: 'with description' },

  // Should NOT match (fields with values)
  { text: '- **Tier**: limited', shouldMatch: false, desc: 'with value after colon' },
  { text: '- **Tier:** **limited**', shouldMatch: false, desc: 'with value, colon inside bold' },
  { text: '- **Data sources**: training, runtime', shouldMatch: false, desc: 'with multiple values' },
];

console.log('Testing EMPTY_FIELD regex:\n');
let allPassed = true;

testCases.forEach(({ text, shouldMatch, desc }) => {
  const matches = EMPTY_FIELD.test(text);
  const passed = matches === shouldMatch;
  allPassed = allPassed && passed;

  const status = passed ? '✓ PASS' : '✗ FAIL';
  const result = matches ? 'matches' : 'does not match';
  console.log(`${status}: "${text}"`);
  console.log(`      Expected: ${shouldMatch ? 'should match' : 'should not match'}`);
  console.log(`      Got: ${result}`);
  console.log(`      (${desc})\n`);
});

if (allPassed) {
  console.log('All tests passed!');
  process.exit(0);
} else {
  console.log('Some tests failed!');
  process.exit(1);
}

