const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^:*]*:?\*\*\s*(\([^)]*\))?\s*:?\s*$/;
const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
const NEEDS_HUMAN_INPUT = /NEEDS\s+HUMAN\s+INPUT/i;

// Test with the reference spec
const refSpecPath = '/private/tmp/100-tricks-runs/pilot-models/without/h1-draft-check/r2/examples/support-triage-demo/rai-gate-draft.reference.md';
const refSpec = fs.readFileSync(refSpecPath, 'utf8');

// Test with the template
const templatePath = '/private/tmp/100-tricks-runs/pilot-models/without/h1-draft-check/r2/packages/frai-gate/assets/rai-spec-template.md';
const template = fs.readFileSync(templatePath, 'utf8');

// Test with a passing example
const examplePath = '/private/tmp/100-tricks-runs/pilot-models/without/h1-draft-check/r2/examples/frai-spec-example.md';
const example = fs.readFileSync(examplePath, 'utf8');

console.log('=== Testing EMPTY_FIELD detection ===\n');

// Extract and test the "Risk tier" section from reference spec
const riskTierMatch = refSpec.match(/### Risk tier\n([\s\S]*?)(?=\n###|$)/);
if (riskTierMatch) {
  console.log('Reference spec "Risk tier" section:');
  const body = riskTierMatch[1];
  const lines = body.split(/\r?\n/);

  lines.forEach((line, i) => {
    const isEmpty = EMPTY_FIELD.test(line);
    const hasPlaceholder = PLACEHOLDER.test(line);
    const hasNeedsInput = NEEDS_HUMAN_INPUT.test(line);

    if (isEmpty || hasPlaceholder || hasNeedsInput) {
      console.log(`Line ${i}: ${isEmpty ? '[EMPTY_FIELD]' : ''} ${hasPlaceholder ? '[PLACEHOLDER]' : ''} ${hasNeedsInput ? '[NEEDS_HUMAN_INPUT]' : ''}`);
      console.log(`  "${line.substring(0, 80)}${line.length > 80 ? '...' : ''}"`);
    }
  });

  // Check for NEEDS HUMAN INPUT
  const hasNeedsInputInSection = NEEDS_HUMAN_INPUT.test(body);
  console.log(`\nHas unresolved NEEDS HUMAN INPUT: ${hasNeedsInputInSection ? 'YES (should BLOCK)' : 'NO'}`);
}

console.log('\n=== Testing template ===\n');

// Extract and test the "Risk tier" section from template
const templateRiskTierMatch = template.match(/### 1 · 🎯 Risk tier\n([\s\S]*?)(?=\n###|$)/);
if (templateRiskTierMatch) {
  console.log('Template "Risk tier" section:');
  const body = templateRiskTierMatch[1];
  const lines = body.split(/\r?\n/);

  lines.forEach((line, i) => {
    const isEmpty = EMPTY_FIELD.test(line);
    if (isEmpty) {
      console.log(`Line ${i}: [EMPTY_FIELD]`);
      console.log(`  "${line}"`);
    }
  });
}

console.log('\n=== Testing passing example ===\n');

// Extract and test the "Risk tier" section from example
const exampleRiskTierMatch = example.match(/### Risk tier\n([\s\S]*?)(?=\n###|$)/);
if (exampleRiskTierMatch) {
  console.log('Example "Risk tier" section:');
  const body = exampleRiskTierMatch[1];

  // Check for NEEDS HUMAN INPUT
  const hasNeedsInputInSection = NEEDS_HUMAN_INPUT.test(body);
  console.log(`Has unresolved NEEDS HUMAN INPUT: ${hasNeedsInputInSection ? 'YES' : 'NO (correct)'}`);

  const lines = body.split(/\r?\n/);
  let emptyFieldCount = 0;
  lines.forEach((line) => {
    if (EMPTY_FIELD.test(line)) {
      emptyFieldCount++;
    }
  });
  console.log(`Empty fields: ${emptyFieldCount} (should be 0)`);
}

console.log('\n=== Summary ===\n');
console.log('✓ EMPTY_FIELD regex correctly identifies empty vs filled fields');
console.log('✓ NEEDS HUMAN INPUT detection identifies unresolved items');
console.log('✓ Template shows expected empty fields');
console.log('✓ Examples show no empty fields and no NEEDS HUMAN INPUT');

